  ('091c5a7d-7759-4833-8519-e2aefda64c77', N'Monitoring & ECG', 'monitoring-ecg', N'Moniteurs multiparamètres, électrocardiographes et oxymètres pour la surveillance continue du patient.', 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=800', NULL, 4, 'Active', '2026-04-21T19:22:30Z', '2026-04-21T19:22:30Z'),
