  ('a013d5dd-fcd2-40c7-b5d7-0b1e8728170e', N'Laboratoire', 'laboratoire', N'Centrifugeuses, microscopes, analyseurs et consommables pour les laboratoires d''''analyse médicale.', 'https://images.unsplash.com/photo-1582560475093-ba66accbc424?w=800', NULL, 6, 'Active', '2026-04-21T19:22:30Z', '2026-04-21T19:22:30Z'),
